          var bestIdx = 0;
          for (var c = 0; c < colorCount; c++) {
            var dr = data[i] - palette[c * 3];
            var dg = data[i + 1] - palette[c * 3 + 1];
            var db = data[i + 2] - palette[c * 3 + 2];
            var diff = dr * dr + dg * dg + db * db;
            if (diff < minDiff) {
              minDiff = diff;
              bestIdx = c;
            }
          }
          colorMap[key] = bestIdx;
